import React, { useMemo } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  Grid,
  Typography,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  CO2E_METHODOLOGY_SUBTITLE,
  GHG_SCOPE_COLORS,
  GHG_SCOPE_HEX,
  formatAxisTickKg,
  maxKgFromRows,
  rechartsCountTooltipFormatter,
  rechartsEmissionsTooltipFormatter,
  rechartsKgValueAxisLabelProps,
  rechartsPercentAxisLabelProps,
  rechartsPercentTooltipFormatter,
} from '../../constants/carbonVisualization';
import {
  axisTickForMode,
  cartesianGridStroke,
  chartAnimationPropsFor,
  rechartsLegendProps,
  rechartsTooltipProps,
} from '../../theme/rechartsAppearances';
import { usePrefersReducedMotion } from '../../hooks/usePrefersReducedMotion';
import {
  buildBenchmarkBulletRows,
  buildHotspotLollipops,
  complianceDonutSegments,
} from '../../utils/carbonAnalyticsChartData';

export type ReportingCarbonFootprintPayload = {
  carbonData?: Array<{ month?: string; carbonFootprint?: number; target?: number }>;
  categoryData?: Array<{ name?: string; value?: number }>;
  scopeData?: {
    scope1?: { total?: number };
    scope2?: { total?: number };
    scope3?: { total?: number };
    total?: number;
  };
};

export type ReportingComparisonsPayload = {
  industryAverage?: number;
  userPerformance?: number;
  benchmarkData?: Array<{ category?: string; user?: number; industry?: number }>;
};

type HotspotRow = {
  rank: number;
  hotspot: string;
  emissionsKgCO2e: number;
  sharePercent: number;
};

type ValueChainStage = {
  label: string;
  contributionPercent: number;
};

export type ReportingCarbonAnalyticsPanelProps = {
  footprint: ReportingCarbonFootprintPayload | null;
  comparisons: ReportingComparisonsPayload | null;
  hotspots?: HotspotRow[];
  valueChainStages?: ValueChainStage[];
  sectorFocus?: Array<{ label: string; emissionsKgCO2e: number }>;
  isoComplianceChecks?: Array<{ id: string; label?: string; status: string; score?: number }>;
  totalEmissionsKg?: number;
};

const ReportingCarbonAnalyticsPanel: React.FC<ReportingCarbonAnalyticsPanelProps> = ({
  footprint,
  comparisons,
  hotspots = [],
  valueChainStages = [],
  sectorFocus = [],
  isoComplianceChecks = [],
  totalEmissionsKg,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const chartGrid = cartesianGridStroke(isDark);
  const chartTip = rechartsTooltipProps(isDark);
  const tickAxis = axisTickForMode(isDark);
  const chartMotion = chartAnimationPropsFor(usePrefersReducedMotion());

  const scopePie = useMemo(() => {
    const s = footprint?.scopeData;
    if (!s) return [];
    return [
      { name: 'Scope 1', value: Number(s.scope1?.total) || 0 },
      { name: 'Scope 2', value: Number(s.scope2?.total) || 0 },
      { name: 'Scope 3', value: Number(s.scope3?.total) || 0 },
    ].filter((row) => row.value > 0);
  }, [footprint?.scopeData]);

  const trendRows = useMemo(
    () =>
      (footprint?.carbonData || [])
        .map((row) => ({
          period: String(row.month || ''),
          emissions: Number(row.carbonFootprint) || 0,
          target: Number(row.target) || 0,
        }))
        .filter((row) => row.period),
    [footprint?.carbonData]
  );

  const hotspotChart = useMemo(
    () =>
      buildHotspotLollipops(
        hotspots.map((h) => ({
          id: `h-${h.rank}`,
          label: h.hotspot,
          co2: h.emissionsKgCO2e,
        }))
      ),
    [hotspots]
  );

  const benchmarkRows = useMemo(() => {
    const total = Number(totalEmissionsKg) || Number(footprint?.scopeData?.total) || 0;
    return buildBenchmarkBulletRows(total, {
      industryAverageKg: (Number(comparisons?.industryAverage) || 0) * 1000,
    });
  }, [comparisons?.industryAverage, footprint?.scopeData?.total, totalEmissionsKg]);

  const complianceDonut = useMemo(
    () =>
      complianceDonutSegments(
        isoComplianceChecks.map((c) => ({
          status: c.status === 'pass' || c.status === 'Pass' ? 'pass' : 'gap',
        }))
      ),
    [isoComplianceChecks]
  );

  const sectorBar = useMemo(
    () =>
      [...sectorFocus]
        .filter((c) => Number(c.emissionsKgCO2e) > 0)
        .sort((a, b) => b.emissionsKgCO2e - a.emissionsKgCO2e)
        .slice(0, 8),
    [sectorFocus]
  );

  const valueChainBar = useMemo(
    () => valueChainStages.filter((s) => Number(s.contributionPercent) > 0),
    [valueChainStages]
  );

  const maxTrend = Math.max(...trendRows.map((r) => r.emissions), 1);
  const hotspotMaxKg = maxKgFromRows(hotspotChart, (r) => Number(r.emissions) || 0);
  const sectorMaxKg = maxKgFromRows(sectorBar, (r) => Number(r.emissionsKgCO2e) || 0);
  const benchmarkMaxKg = maxKgFromRows(benchmarkRows, (r) => Number(r.value) || 0);

  const hasAnyChart =
    scopePie.length > 0
    || trendRows.length > 0
    || hotspotChart.length > 0
    || benchmarkRows.length > 0
    || complianceDonut.length > 0
    || sectorBar.length > 0
    || valueChainBar.length > 0;

  if (!hasAnyChart) {
    return (
      <Alert severity="info" sx={{ mb: 2 }}>
        Complete a carbon assessment for this period to unlock GHG scope analytics, sector hotspots, and benchmark
        comparisons aligned to disclosure standards.
      </Alert>
    );
  }

  return (
    <Box sx={{ mb: 3 }}>
      <Typography variant="h6" gutterBottom>
        Carbon analytics (reporting period)
      </Typography>
      <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
        {CO2E_METHODOLOGY_SUBTITLE} Charts use the same palette and units as Carbon Analytics and exported PDFs.
      </Typography>
      <Grid container spacing={3}>
        {scopePie.length > 0 && (
          <Grid item xs={12} md={4}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  Scope inventory split
                </Typography>
                <ResponsiveContainer width="100%" height={240}>
                  <PieChart>
                    <Pie
                      data={scopePie}
                      dataKey="value"
                      nameKey="name"
                      innerRadius={50}
                      outerRadius={82}
                      paddingAngle={2}
                      label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                      {...chartMotion}
                    >
                      {[GHG_SCOPE_HEX.scope1, GHG_SCOPE_HEX.scope2, GHG_SCOPE_HEX.scope3].map((color, idx) => {
                        const sk = `scope${idx + 1}` as 'scope1' | 'scope2' | 'scope3';
                        return (
                          <Cell
                            key={color}
                            fill={color}
                            stroke={GHG_SCOPE_COLORS[sk].stroke}
                            strokeWidth={1.5}
                          />
                        );
                      })}
                    </Pie>
                    <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                    <Legend {...rechartsLegendProps} />
                  </PieChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        {trendRows.length > 0 && (
          <Grid item xs={12} md={8}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  Emissions trend vs target
                </Typography>
                <ResponsiveContainer width="100%" height={240}>
                  <AreaChart data={trendRows} margin={{ top: 8, right: 16, left: 0, bottom: 4 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                    <XAxis dataKey="period" tick={tickAxis} />
                    <YAxis
                      tick={tickAxis}
                      tickFormatter={(v: number) => formatAxisTickKg(v)}
                      label={{
                        ...rechartsKgValueAxisLabelProps(maxTrend, { fill: tickAxis.fill as string }),
                        style: { fontSize: 10, fill: tickAxis.fill as string },
                      }}
                    />
                    <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                    <Legend {...rechartsLegendProps} />
                    <Area
                      type="monotone"
                      dataKey="emissions"
                      stroke={GHG_SCOPE_HEX.scope2}
                      fill={GHG_SCOPE_HEX.scope2}
                      fillOpacity={0.35}
                      name="Footprint (kg CO₂e)"
                      {...chartMotion}
                    />
                    <Area
                      type="monotone"
                      dataKey="target"
                      stroke="#94a3b8"
                      fill="#94a3b8"
                      fillOpacity={0.15}
                      name="Target (kg CO₂e)"
                      {...chartMotion}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        {hotspotChart.length > 0 && (
          <Grid item xs={12} md={6}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  Emission hotspots (BRSR)
                </Typography>
                <ResponsiveContainer width="100%" height={260}>
                  <BarChart data={hotspotChart} layout="vertical" margin={{ top: 4, right: 12, left: 8, bottom: 4 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} horizontal={false} />
                    <XAxis
                      type="number"
                      tick={tickAxis}
                      tickFormatter={(v: number) => formatAxisTickKg(v)}
                      label={rechartsKgValueAxisLabelProps(hotspotMaxKg, { fill: tickAxis.fill as string, vertical: false })}
                    />
                    <YAxis type="category" dataKey="label" width={120} tick={tickAxis} />
                    <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                    <Bar dataKey="emissions" name="kg CO₂e" fill="#0d9488" radius={[0, 6, 6, 0]} {...chartMotion} />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        {sectorBar.length > 0 && (
          <Grid item xs={12} md={6}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  Sector focus categories
                </Typography>
                <ResponsiveContainer width="100%" height={260}>
                  <BarChart data={sectorBar} margin={{ top: 8, right: 8, left: 0, bottom: 4 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                    <XAxis dataKey="label" interval={0} angle={-14} textAnchor="end" height={64} tick={tickAxis} />
                    <YAxis
                      tick={tickAxis}
                      tickFormatter={(v: number) => formatAxisTickKg(v)}
                      label={{
                        ...rechartsKgValueAxisLabelProps(sectorMaxKg, { fill: tickAxis.fill as string }),
                        style: { fontSize: 10, fill: tickAxis.fill as string },
                      }}
                    />
                    <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                    <Bar dataKey="emissionsKgCO2e" fill="#0284c7" name="kg CO₂e" radius={[6, 6, 0, 0]} {...chartMotion} />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        {valueChainBar.length > 0 && (
          <Grid item xs={12} md={6}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  Value chain stage contribution
                </Typography>
                <ResponsiveContainer width="100%" height={240}>
                  <BarChart data={valueChainBar} margin={{ top: 8, right: 8, left: 0, bottom: 4 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                    <XAxis dataKey="label" tick={tickAxis} interval={0} angle={-12} textAnchor="end" height={56} />
                    <YAxis
                      tick={tickAxis}
                      domain={[0, 100]}
                      tickFormatter={(v: number) => `${v}%`}
                      label={{
                        ...rechartsPercentAxisLabelProps({ fill: tickAxis.fill as string }),
                        style: { fontSize: 10, fill: tickAxis.fill as string },
                      }}
                    />
                    <Tooltip {...chartTip} formatter={rechartsPercentTooltipFormatter} />
                    <Bar dataKey="contributionPercent" fill="#7c3aed" name="% of total" radius={[6, 6, 0, 0]} {...chartMotion} />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        {complianceDonut.length > 0 && (
          <Grid item xs={12} md={6}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  ISO 14064 compliance checks
                </Typography>
                <ResponsiveContainer width="100%" height={240}>
                  <PieChart>
                    <Pie
                      data={complianceDonut}
                      dataKey="value"
                      nameKey="name"
                      innerRadius={48}
                      outerRadius={80}
                      paddingAngle={2}
                      {...chartMotion}
                    >
                      {complianceDonut.map((entry, idx) => (
                        <Cell key={entry.name} fill={['#059669', '#f59e0b', '#94a3b8'][idx % 3]} />
                      ))}
                    </Pie>
                    <Tooltip {...chartTip} formatter={rechartsCountTooltipFormatter} />
                    <Legend {...rechartsLegendProps} />
                  </PieChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        {benchmarkRows.length > 0 && (
          <Grid item xs={12} md={6}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography variant="subtitle2" gutterBottom>
                  Performance vs industry benchmark
                </Typography>
                <ResponsiveContainer width="100%" height={240}>
                  <BarChart data={benchmarkRows} margin={{ top: 8, right: 8, left: 0, bottom: 4 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                    <XAxis dataKey="label" tick={tickAxis} />
                    <YAxis
                      tick={tickAxis}
                      tickFormatter={(v: number) => formatAxisTickKg(v)}
                      label={{
                        ...rechartsKgValueAxisLabelProps(benchmarkMaxKg, { fill: tickAxis.fill as string }),
                        style: { fontSize: 10, fill: tickAxis.fill as string },
                      }}
                    />
                    <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                    <Bar dataKey="value" name="kg CO₂e" fill="#0d9488" radius={[6, 6, 0, 0]} {...chartMotion} />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>
        )}
      </Grid>
    </Box>
  );
};

export default ReportingCarbonAnalyticsPanel;
